-- PRE-GO-LIVE INTEGRITY CORRECTION: the accepted SAAS-01 migration contained corrupted currency CHECK SQL and could not execute on a fresh database. The intended rule remains exactly three uppercase ASCII letters.
CREATE TABLE "saas_tenants" ("company_id" TEXT NOT NULL,"company_code" TEXT NOT NULL,"mode" TEXT NOT NULL DEFAULT 'SUBSCRIPTION',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "saas_tenants_pkey" PRIMARY KEY ("company_id"));
CREATE UNIQUE INDEX "saas_tenants_company_code_key" ON "saas_tenants"("company_code");
CREATE TABLE "saas_plans" ("id" TEXT NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"interval_months" INTEGER NOT NULL,"price_minor" INTEGER NOT NULL,"currency" TEXT NOT NULL,"entitlements" JSONB NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "saas_plans_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "saas_plans_code_key" ON "saas_plans"("code");
CREATE TABLE "saas_subscriptions" ("id" TEXT NOT NULL,"company_id" TEXT NOT NULL,"plan_id" TEXT NOT NULL,"status" TEXT NOT NULL,"current_period_start" TIMESTAMP(3) NOT NULL,"current_period_end" TIMESTAMP(3) NOT NULL,"grace_period_end" TIMESTAMP(3),"entitlements_snapshot" JSONB NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "saas_subscriptions_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "saas_subscriptions_company_id_key" ON "saas_subscriptions"("company_id");
CREATE INDEX "saas_subscriptions_status_current_period_end_idx" ON "saas_subscriptions"("status","current_period_end");
CREATE TABLE "saas_payments" ("id" TEXT NOT NULL,"company_id" TEXT NOT NULL,"subscription_id" TEXT NOT NULL,"provider" TEXT NOT NULL,"reference" TEXT NOT NULL,"amount_minor" INTEGER NOT NULL,"currency" TEXT NOT NULL,"idempotency_key" TEXT NOT NULL,"payload_hash" TEXT NOT NULL,"paid_at" TIMESTAMP(3) NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "saas_payments_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "saas_payments_idempotency_key_key" ON "saas_payments"("idempotency_key");
CREATE UNIQUE INDEX "saas_payments_company_id_provider_reference_key" ON "saas_payments"("company_id","provider","reference");
CREATE INDEX "saas_payments_company_id_paid_at_idx" ON "saas_payments"("company_id","paid_at");
CREATE TABLE "saas_owner_accounts" ("id" TEXT NOT NULL,"email" TEXT NOT NULL,"password_hash" TEXT NOT NULL,"mfa_secret_cipher" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"failed_attempts" INTEGER NOT NULL DEFAULT 0,"locked_until" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "saas_owner_accounts_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "saas_owner_accounts_email_key" ON "saas_owner_accounts"("email");
CREATE TABLE "saas_owner_sessions" ("id" TEXT NOT NULL,"owner_id" TEXT NOT NULL,"token_hash" TEXT NOT NULL,"authenticated_at" TIMESTAMP(3) NOT NULL,"expires_at" TIMESTAMP(3) NOT NULL,"revoked_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "saas_owner_sessions_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "saas_owner_sessions_token_hash_key" ON "saas_owner_sessions"("token_hash");
CREATE INDEX "saas_owner_sessions_owner_id_expires_at_idx" ON "saas_owner_sessions"("owner_id","expires_at");
CREATE TABLE "saas_subscription_events" ("id" TEXT NOT NULL,"company_id" TEXT NOT NULL,"subscription_id" TEXT NOT NULL,"kind" TEXT NOT NULL,"from_status" TEXT,"to_status" TEXT NOT NULL,"owner_id" TEXT NOT NULL,"payment_id" TEXT,"period_start" TIMESTAMP(3) NOT NULL,"period_end" TIMESTAMP(3) NOT NULL,"metadata" JSONB NOT NULL DEFAULT '{}',"occurred_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "saas_subscription_events_pkey" PRIMARY KEY ("id"));
CREATE INDEX "saas_subscription_events_company_id_occurred_at_idx" ON "saas_subscription_events"("company_id","occurred_at");
CREATE TABLE "saas_control_events" ("id" TEXT NOT NULL,"owner_id" TEXT,"action" TEXT NOT NULL,"target_type" TEXT NOT NULL,"target_id" TEXT,"company_id" TEXT,"metadata" JSONB NOT NULL DEFAULT '{}',"occurred_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "saas_control_events_pkey" PRIMARY KEY ("id"));
CREATE INDEX "saas_control_events_company_id_occurred_at_idx" ON "saas_control_events"("company_id","occurred_at");
CREATE INDEX "saas_control_events_owner_id_occurred_at_idx" ON "saas_control_events"("owner_id","occurred_at");
ALTER TABLE "saas_subscriptions" ADD CONSTRAINT "saas_subscriptions_company_id_fkey" FOREIGN KEY ("company_id") REFERENCES "saas_tenants"("company_id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "saas_subscriptions" ADD CONSTRAINT "saas_subscriptions_plan_id_fkey" FOREIGN KEY ("plan_id") REFERENCES "saas_plans"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "saas_payments" ADD CONSTRAINT "saas_payments_company_id_fkey" FOREIGN KEY ("company_id") REFERENCES "saas_tenants"("company_id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "saas_payments" ADD CONSTRAINT "saas_payments_subscription_id_fkey" FOREIGN KEY ("subscription_id") REFERENCES "saas_subscriptions"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "saas_owner_sessions" ADD CONSTRAINT "saas_owner_sessions_owner_id_fkey" FOREIGN KEY ("owner_id") REFERENCES "saas_owner_accounts"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "saas_subscription_events" ADD CONSTRAINT "saas_subscription_events_company_id_fkey" FOREIGN KEY ("company_id") REFERENCES "saas_tenants"("company_id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "saas_subscription_events" ADD CONSTRAINT "saas_subscription_events_subscription_id_fkey" FOREIGN KEY ("subscription_id") REFERENCES "saas_subscriptions"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "saas_subscription_events" ADD CONSTRAINT "saas_subscription_events_owner_id_fkey" FOREIGN KEY ("owner_id") REFERENCES "saas_owner_accounts"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "saas_subscription_events" ADD CONSTRAINT "saas_subscription_events_payment_id_fkey" FOREIGN KEY ("payment_id") REFERENCES "saas_payments"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "saas_control_events" ADD CONSTRAINT "saas_control_events_owner_id_fkey" FOREIGN KEY ("owner_id") REFERENCES "saas_owner_accounts"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "saas_tenants" ADD CONSTRAINT "saas_tenants_mode_check" CHECK ("mode" IN ('INTERNAL','SUBSCRIPTION'));
ALTER TABLE "saas_plans" ADD CONSTRAINT "saas_plans_interval_check" CHECK ("interval_months" BETWEEN 1 AND 24), ADD CONSTRAINT "saas_plans_price_check" CHECK ("price_minor" >= 0), ADD CONSTRAINT "saas_plans_currency_check" CHECK (char_length("currency") = 3 AND "currency" ~ '^[A-Z]{3}');
ALTER TABLE "saas_subscriptions" ADD CONSTRAINT "saas_subscriptions_status_check" CHECK ("status" IN ('ACTIVE','PAST_DUE','SUSPENDED','CANCELLED')), ADD CONSTRAINT "saas_subscriptions_period_check" CHECK ("current_period_end" > "current_period_start"), ADD CONSTRAINT "saas_subscriptions_version_check" CHECK ("version" >= 1);
ALTER TABLE "saas_payments" ADD CONSTRAINT "saas_payments_amount_check" CHECK ("amount_minor" >= 0), ADD CONSTRAINT "saas_payments_provider_check" CHECK ("provider" IN ('MANUAL','PAYMENT_PROVIDER')), ADD CONSTRAINT "saas_payments_currency_check" CHECK (char_length("currency") = 3 AND "currency" ~ '^[A-Z]{3}');
ALTER TABLE "saas_owner_accounts" ADD CONSTRAINT "saas_owner_accounts_status_check" CHECK ("status" IN ('ACTIVE','DISABLED')), ADD CONSTRAINT "saas_owner_accounts_failures_check" CHECK ("failed_attempts" >= 0);

INSERT INTO "saas_tenants" ("company_id","company_code","mode","created_at","updated_at") SELECT "id",'ELH-' || UPPER(SUBSTRING(MD5("id") FROM 1 FOR 16)),'INTERNAL',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM "pc_companies" ON CONFLICT ("company_id") DO NOTHING;
